import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the last day of the month for a given date.
 * @param {string} date - date in YYYY-MM-DD format
 * @returns {string} - last day of the month in YYYY-MM-DD format
 */
function lastDayOfMonth(date) {
  const d = new Date(date + 'T00:00:00Z');
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  const lastDay = new Date(Date.UTC(year, month + 1, 0));
  return lastDay.toISOString().split('T')[0];
}

/**
 * Calculate due date based on payment terms.
 * @param {string} issueDate - date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') return lastDayOfMonth(issueDate);
  return null;
}

/**
 * Create a new invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issue date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) return fail('TERMS_INVALID');
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines is not empty
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    const { sku, qty, discountPercent } = line;

    // Validate qty is a positive integer
    if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

    // Determine discount: use line's discountPercent if provided, else use tier discount
    let finalDiscount;
    if ('discountPercent' in line) {
      finalDiscount = discountPercent;
    } else {
      finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
    }

    // Validate discountPercent
    if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(sku);
    if (!productResult.ok) return productResult;

    const { name, unitPrice, vatRate } = productResult.value;
    enrichedLines.push({
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Calculate the total for a single line item: qty × unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice: subtotal, discount, VAT, voucher, and total.
 * @param {{ lines: Array, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVALID_INVOICE');
  }
  let subtotal = 0;
  let discount = 0;
  let vat = 0;
  for (const line of invoice.lines) {
    const lineGrossTotal = lineTotal(line);
    subtotal += lineGrossTotal;
    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(lineGrossTotal * discountPercent / 100);
    discount += lineDiscount;
    const lineAmount = Math.max(0, lineGrossTotal - lineDiscount);
    const vatRate = line.vatRate ?? 0;
    const lineVat = roundCents(lineAmount * vatRate / 100);
    vat += lineVat;
  }
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
  return ok({
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    voucher: Math.max(0, voucher),
    total,
  });
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array, customerId: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, params) {
  const { sku, qty, discountPercent } = params;

  // Check status and structure
  if (!invoice || invoice.status !== 'draft' || !Array.isArray(invoice.lines)) {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Determine discount: use line's discountPercent if provided, else use tier discount
  let finalDiscount;
  if ('discountPercent' in params) {
    finalDiscount = discountPercent;
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) return customerResult;
    finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  }

  // Validate discountPercent
  if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const { name, unitPrice, vatRate } = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Find existing line with this SKU
  const existingIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingIndex >= 0) {
    // Increase qty on existing line
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name,
      qty,
      unitPrice,
      vatRate,
      discountPercent: finalDiscount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status and structure
  if (!invoice || invoice.status !== 'draft' || !Array.isArray(invoice.lines)) {
    return fail('NOT_DRAFT');
  }

  // Find line with this SKU
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, params) {
  const { code, amount } = params;

  // Check invoice is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount is a positive integer
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

