import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  const line = r.value.lines[0];
  assert.equal(line.sku, 'DES-HOUR');
  assert.equal(line.name, 'Design work (hour)');
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, 8500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice normalizes lowercase customer id', () => {
  const r = createInvoice({
    customerId: 'c-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice normalizes customer id with spaces', () => {
  const r = createInvoice({
    customerId: '  C-003  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
});

test('createInvoice normalizes mixed case id with spaces', () => {
  const r = createInvoice({
    customerId: '  c-007 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-007');
});

test('createInvoice includes multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
});

test('createInvoice rejects an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects an invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an invalid date value', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects missing lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects a non-integer quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects a negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects an unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, linesCopy);
});

test('createInvoice returns a copy of the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.notEqual(r1.value, r2.value);
  assert.notEqual(r1.value.lines, r2.value.lines);
});

test('lineTotal calculates qty × unitPrice', () => {
  const total = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(total, 42500);
});

test('lineTotal with qty 1', () => {
  const total = lineTotal({ qty: 1, unitPrice: 8500 });
  assert.equal(total, 8500);
});

test('lineTotal with qty 0 returns 0', () => {
  const total = lineTotal({ qty: 0, unitPrice: 8500 });
  assert.equal(total, 0);
});

test('invoiceTotals calculates subtotal from a single line', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 5, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 42500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 42500);
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 2, unitPrice: 8500, vatRate: 0 },
      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, vatRate: 0 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 2 * 8500 + 3 * 9500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, r.value.subtotal);
});

test('invoiceTotals with empty lines returns 0', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 0);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals with createInvoice result', () => {
  const created = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r = invoiceTotals(created.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 8500);
  assert.equal(r.value.discount, 1062);
  const lineAmount = 5 * 8500 - 1062;
  const vat = Math.round(lineAmount * 21 / 100);
  assert.equal(r.value.vat, vat);
  assert.equal(r.value.total, 5 * 8500 - 1062 + vat);
});

test('invoiceTotals rejects null invoice', () => {
  const r = invoiceTotals(null);
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals rejects invoice without lines', () => {
  const r = invoiceTotals({ customerId: 'C-003' });
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals rejects invoice with non-array lines', () => {
  const r = invoiceTotals({ customerId: 'C-003', lines: 'not an array' });
  assert.deepEqual(r, { ok: false, error: 'INVALID_INVOICE' });
});

test('addLine adds a new line to a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 3);
  assert.equal(r.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;
  const originalLength = invoice.lines.length;
  const originalQty = invoice.lines[0].qty;
  addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(invoice.lines.length, originalLength);
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('addLine validates qty like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU like createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const r = addLine(invoice, { sku: 'UNKNOWN', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine refuses to modify null or invalid invoice', () => {
  const r1 = addLine(null, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r1, { ok: false, error: 'NOT_DRAFT' });
  const r2 = addLine({ status: 'draft' }, { sku: 'DES-HOUR', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine removes a line from a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const r = removeLine(invoice, 'DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  }).value;
  const originalLength = invoice.lines.length;
  removeLine(invoice, 'DES-HOUR');
  assert.equal(invoice.lines.length, originalLength);
});

test('removeLine rejects unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const r = removeLine(invoice, 'UNKNOWN');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine rejects removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = removeLine(invoice, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine refuses to modify null or invalid invoice', () => {
  const r1 = removeLine(null, 'DES-HOUR');
  assert.deepEqual(r1, { ok: false, error: 'NOT_DRAFT' });
  const r2 = removeLine({ status: 'draft' }, 'DES-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
  assert.equal(r.value.status, 'issued');
  assert.equal(r.value.customerId, invoice.customerId);
  assert.equal(r.value.issueDate, invoice.issueDate);
});

test('issueInvoice with existing numbers', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice with different year', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
